Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
using namespace std;

long long A[20];

long long compute_min(int level, long long val) {
    if (level == 0)
        return val == 0 ? 0 : 100000000;
    if (val < 0) val = -val;
    long long quotient = val / A[level];
    long long option1 = compute_min(level - 1, val - quotient * A[level]) + quotient * level;
    long long option2 = compute_min(level - 1, val - (quotient + 1) * A[level]) + (quotient + 1) * level;
    return min(option1, option2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    A[0] = 1;
    for (int i = 1; i <= 16; ++i)
        A[i] = A[i - 1] * 10 + 1;
    cout << compute_min(16, n) << '\n';
    return 0;
}
</original_code>
